    """Evaluate the unital twisted product on natural numbers."""
    if a < 0 or b < 0:
        raise ValueError("inputs must be natural numbers")
    if a == 0:
        return b
    if b == 0:
        return a
    return a + 2 * b

if __name__ == "__main__":
    for a in range(6):
        assert twisted_comp(0, a) == a == twisted_comp(a, 0)
    left = twisted_comp(twisted_comp(1, 1), 1)
    right = twisted_comp(1, twisted_comp(1, 1))
    print(f"left bracketing = {left}, right bracketing = {right}")
    assert (left, right) == (5, 7)

from __future__ import annotations

def twisted_comp(a: int, b: int) -> int:
    if a < 0 or b < 0:
        raise ValueError("inputs must be natural numbers")
    if a == 0: return b
    if b == 0: return a
    return a + 2 * b

def defect(a: int, b: int, c: int) -> int:
    left = twisted_comp(twisted_comp(a, b), c)
    right = twisted_comp(a, twisted_comp(b, c))
    return right - left

if __name__ == "__main__":
    for c in range(1, 8):
        observed = defect(1, 1, c)
        print(c, observed)
        assert observed == 2 * c

